CREATE TEMP TABLE reviewed_batch(draft bigint, source int, fp text, draft_hash text, source_hex text, snapshot jsonb, wizard jsonb, metadata text, flat_ar text, flat_en text) ON COMMIT DROP;
INSERT INTO reviewed_batch VALUES
(365,144,$mw$FDD80C87D504B79A2ED04F85C604B450A4DB8DAE3E9D3C088B6F71C94FBC3FCE$mw$,$mw$4054d9d17a2c4006857fc344a9548248$mw$,$mw$$mw$,$mw${"Id":144,"StageId":4,"CategoryId":16,"Points":15,"TitleAr":"الدالة f متصلة على [0,2] وتحقق f(0)=-3 وf(2)=2. ما النتيجة المضمونة؟","TitleEn":"f is continuous on [0,2], f(0)=-3 and f(2)=2. Which statement is guaranteed?","QuestionTextAr":"الدالة f متصلة على [0,2] وتحقق f(0)=-3 وf(2)=2. ما النتيجة المضمونة؟","QuestionTextEn":"f is continuous on [0,2], f(0)=-3 and f(2)=2. Which statement is guaranteed?","DetailedSolutionAr":"مبرهنة القيمة الوسيطة: إذا كانت دالة متصلة على [0،2] فإنها تأخذ كل قيمة بين قيمتي الطرفين. بما أن f(0)=-3 سالب وf(2)=2 موجب، فالصفر يقع بينهما. لذلك توجد نقطة ج داخل (0،2) تحقق f(ج)=0. لا تضمن المبرهنة تفرد هذا الجذر.","DetailedSolutionEn":"Intermediate Value Theorem: Continuity on [0,2] ensures every output between f(0)=-3 and f(2)=2 is attained. Since zero lies between opposite-sign endpoint values, some c in (0,2) satisfies f(c)=0. Uniqueness is not guaranteed.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":565,"Order":1,"LatexCode":"\\exists c\\in(0,2):f(c)=0","IsCorrect":true},{"Id":566,"Order":2,"LatexCode":"f(1)=0","IsCorrect":false},{"Id":567,"Order":3,"LatexCode":"f'(1)=0","IsCorrect":false},{"Id":568,"Order":4,"LatexCode":"f(x)>0\\;\\forall x\\in(0,2)","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"قارن إشارات قيمتي الدالة عند الطرفين.","En":"Compare the signs at the two endpoints."},{"Ar":"طبق نظرية القيمة الوسيطة على القيمة صفر.","En":"Apply the intermediate value theorem to the value zero."}],"Title":{"Ar":"الدالة f متصلة على [0,2] وتحقق f(0)=-3 وf(2)=2. ما النتيجة المضمونة؟","En":"f is continuous on [0,2], f(0)=-3 and f(2)=2. Which statement is guaranteed?"},"Points":15,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"\\exists c\\in(0,2):f(c)=0"},{"Reason":{"Ar":"لا يلزم أن يقع الجذر عند 1؛ مثلاً الدالة الخطية التي تصل الطرفين جذرها 6/5.","En":"The root need not be at 1; for example the line joining the endpoints has root 6/5."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"f(1)=0"},{"Reason":{"Ar":"الاتصال لا يضمن قابلية الاشتقاق، وحتى الدالة الخطية الموافقة لها مشتقة 5/2.","En":"Continuity does not imply differentiability; even the matching linear function has derivative 5/2."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"f'(1)=0"},{"Reason":{"Ar":"وجود جذر داخل المجال يناقض الإيجابية الصارمة في كل نقطة داخله.","En":"An interior root contradicts strict positivity throughout the interior."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"f(x)>0\\;\\forall x\\in(0,2)"}],"StageId":4,"Question":{"Ar":"الدالة f متصلة على [0,2] وتحقق f(0)=-3 وf(2)=2. ما النتيجة المضمونة؟","En":"f is continuous on [0,2], f(0)=-3 and f(2)=2. Which statement is guaranteed?"},"Solution":{"Idea":{"Ar":"نظرية القيمة الوسيطة تضمن أخذ كل قيمة بين قيمتي طرفي مجال الاتصال.","En":"The intermediate value theorem guarantees all values between continuous endpoint values."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الاتصال على المجال المغلق يحقق فرضية نظرية القيمة الوسيطة.","En":"Continuity on the closed interval satisfies the hypothesis of the intermediate value theorem."},{"Ar":"$f(0)=-3<0<2=f(2)$","En":"$f(0)=-3<0<2=f(2)$"},{"Ar":"الصفر يقع بين قيمتي الطرفين؛ توجد نقطة داخل المجال تكون قيمة الدالة عندها صفراً، دون تحديد موقعها.","En":"Zero lies between the endpoint values; some interior point has function value zero, without specifying its location."}],"Result":{"Ar":"$\\exists c\\in(0,2):f(c)=0$","En":"$\\exists c\\in(0,2):f(c)=0$"},"CommonError":{"Ar":"النظرية تضمن وجود جذر لا موقعه الدقيق أو مشتقته.","En":"The theorem guarantees a root, not its exact location or derivative."},"FormulaLatex":"f(a)f(b)<0\\Rightarrow\\exists c\\in(a,b):f(c)=0","Substitution":{"Ar":"$-3<0<2\\Rightarrow\\exists c\\in(0,2):f(c)=0$","En":"$-3<0<2\\Rightarrow\\exists c\\in(0,2):f(c)=0$"},"Verification":{"Ar":"الاتصال وتعاكس إشارات الطرفين متحققان، وهما كافيان لوجود جذر.","En":"Continuity and opposite endpoint signs are satisfied, which suffice for root existence."}},"TrackIds":[13,20],"CategoryId":16,"PrimarySkillId":73,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"قارن إشارات قيمتي الدالة عند الطرفين.","En":"Compare the signs at the two endpoints."},{"Ar":"طبق نظرية القيمة الوسيطة على القيمة صفر.","En":"Apply the intermediate value theorem to the value zero."}],"Solution":{"Idea":{"Ar":"نظرية القيمة الوسيطة تضمن أخذ كل قيمة بين قيمتي طرفي مجال الاتصال.","En":"The intermediate value theorem guarantees all values between continuous endpoint values."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"الاتصال على المجال المغلق يحقق فرضية نظرية القيمة الوسيطة.","En":"Continuity on the closed interval satisfies the hypothesis of the intermediate value theorem."},{"Ar":"$f(0)=-3<0<2=f(2)$","En":"$f(0)=-3<0<2=f(2)$"},{"Ar":"الصفر يقع بين قيمتي الطرفين؛ توجد نقطة داخل المجال تكون قيمة الدالة عندها صفراً، دون تحديد موقعها.","En":"Zero lies between the endpoint values; some interior point has function value zero, without specifying its location."}],"Result":{"Ar":"$\\exists c\\in(0,2):f(c)=0$","En":"$\\exists c\\in(0,2):f(c)=0$"},"CommonError":{"Ar":"النظرية تضمن وجود جذر لا موقعه الدقيق أو مشتقته.","En":"The theorem guarantees a root, not its exact location or derivative."},"FormulaLatex":"f(a)f(b)<0\\Rightarrow\\exists c\\in(a,b):f(c)=0","Substitution":{"Ar":"$-3<0<2\\Rightarrow\\exists c\\in(0,2):f(c)=0$","En":"$-3<0<2\\Rightarrow\\exists c\\in(0,2):f(c)=0$"},"Verification":{"Ar":"الاتصال وتعاكس إشارات الطرفين متحققان، وهما كافيان لوجود جذر.","En":"Continuity and opposite endpoint signs are satisfied, which suffice for root existence."}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"لا يلزم أن يقع الجذر عند 1؛ مثلاً الدالة الخطية التي تصل الطرفين جذرها 6/5.","En":"The root need not be at 1; for example the line joining the endpoints has root 6/5."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"الاتصال لا يضمن قابلية الاشتقاق، وحتى الدالة الخطية الموافقة لها مشتقة 5/2.","En":"Continuity does not imply differentiability; even the matching linear function has derivative 5/2."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"وجود جذر داخل المجال يناقض الإيجابية الصارمة في كل نقطة داخله.","En":"An interior root contradicts strict positivity throughout the interior."},"Order":4}]}$mw$,$mw$نظرية القيمة الوسيطة تضمن أخذ كل قيمة بين قيمتي طرفي مجال الاتصال.

$f(a)f(b)<0\Rightarrow\exists c\in(a,b):f(c)=0$

1. الاتصال على المجال المغلق يحقق فرضية نظرية القيمة الوسيطة.

2. $f(0)=-3<0<2=f(2)$

3. الصفر يقع بين قيمتي الطرفين؛ توجد نقطة داخل المجال تكون قيمة الدالة عندها صفراً، دون تحديد موقعها.

$-3<0<2\Rightarrow\exists c\in(0,2):f(c)=0$

$\exists c\in(0,2):f(c)=0$ بلا وحدة قياس

الاتصال وتعاكس إشارات الطرفين متحققان، وهما كافيان لوجود جذر.

النظرية تضمن وجود جذر لا موقعه الدقيق أو مشتقته.$mw$,$mw$The intermediate value theorem guarantees all values between continuous endpoint values.

$f(a)f(b)<0\Rightarrow\exists c\in(a,b):f(c)=0$

1. Continuity on the closed interval satisfies the hypothesis of the intermediate value theorem.

2. $f(0)=-3<0<2=f(2)$

3. Zero lies between the endpoint values; some interior point has function value zero, without specifying its location.

$-3<0<2\Rightarrow\exists c\in(0,2):f(c)=0$

$\exists c\in(0,2):f(c)=0$ Dimensionless

Continuity and opposite endpoint signs are satisfied, which suffice for root existence.

The theorem guarantees a root, not its exact location or derivative.$mw$),
(369,148,$mw$487D1970AD1F9808B174CFB7A3748F946232691996BE83689D7A2267A1DEE286$mw$,$mw$b87af7c43a82fdbe7ec913ad8ee284c8$mw$,$mw$$mw$,$mw${"Id":148,"StageId":4,"CategoryId":36,"Points":15,"TitleAr":"أي متسلسلة مما يلي متقاربة؟","TitleEn":"Which of the following series converges?","QuestionTextAr":"أي متسلسلة مما يلي متقاربة؟","QuestionTextEn":"Which of the following series converges?","DetailedSolutionAr":"المتسلسلة من نوع p تتقارب عندما p>1؛ لذلك مجموع 1/n² متقارب.","DetailedSolutionEn":"A p-series converges for p>1, so the sum of 1/n² converges.","YoutubeSolutionUrl":null,"EditorialDetailsJson":null,"Options":[{"Id":581,"Order":1,"LatexCode":"\\sum_{n=1}^{\\infty}\\frac{1}{n^2}","IsCorrect":true},{"Id":582,"Order":2,"LatexCode":"\\sum_{n=1}^{\\infty}\\frac{1}{n}","IsCorrect":false},{"Id":583,"Order":3,"LatexCode":"\\sum_{n=1}^{\\infty}\\frac{1}{\\sqrt{n}}","IsCorrect":false},{"Id":584,"Order":4,"LatexCode":"\\sum_{n=1}^{\\infty}1","IsCorrect":false}]}$mw$::jsonb,$mw${"Hints":[{"Ar":"صنّف المتسلسلات قبل تطبيق اختبار التقارب.","En":"Classify the series before applying a convergence test."},{"Ar":"للمتسلسلة من الشكل واحد على قوة العدد الطبيعي، قارن الأس بواحد.","En":"For a series of reciprocals of natural-number powers, compare the exponent with one."}],"Title":{"Ar":"أي متسلسلة مما يلي متقاربة؟","En":"Which of the following series converges?"},"Points":15,"Options":[{"Reason":null,"ErrorType":"","IsCorrect":true,"LatexCode":"\\sum_{n=1}^{\\infty}\\frac{1}{n^2}"},{"Reason":{"Ar":"المتسلسلة التوافقية لها p=1 وهي متباعدة.","En":"The harmonic series has p=1 and diverges."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"\\sum_{n=1}^{\\infty}\\frac{1}{n}"},{"Reason":{"Ar":"الأس 1/2 لا يتجاوز واحداً، لذا تتباعد.","En":"Exponent 1/2 does not exceed one, so the series diverges."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"\\sum_{n=1}^{\\infty}\\frac{1}{\\sqrt{n}}"},{"Reason":{"Ar":"الحد العام ثابت يساوي 1، فيخالف الشرط الضروري للتقارب.","En":"The constant term 1 violates the necessary condition for convergence."},"ErrorType":"incorrect-option","IsCorrect":false,"LatexCode":"\\sum_{n=1}^{\\infty}1"}],"StageId":4,"Question":{"Ar":"أي متسلسلة مما يلي متقاربة؟","En":"Which of the following series converges?"},"Solution":{"Idea":{"Ar":"معيار متسلسلة القوى العكسية: $\\sum_{n=1}^{\\infty}1/n^p$ تتقارب إذا وفقط إذا $p>1$. هنا $p=2$.","En":"The p-series test: $\\sum_{n=1}^{\\infty}1/n^p$ converges exactly when $p>1$. Here $p=2$."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نستعمل معيار متسلسلة القوى العكسية، الذي يتطلب أساً أكبر من واحد للتقارب.","En":"Use the p-series test, which requires an exponent greater than one for convergence."},{"Ar":"$p=2>1;\\quad p=1,\\quad p=1/2\\le1$","En":"$p=2>1;\\quad p=1,\\quad p=1/2\\le1$"},{"Ar":"المتسلسلة الأولى متقاربة، والثانية والثالثة متباعدتان؛ والمتسلسلة الرابعة متباعدة لأن حدودها لا تؤول إلى الصفر.","En":"The first series converges, the second and third diverge, and the fourth diverges because its terms do not approach zero."}],"Result":{"Ar":"$\\sum_{n=1}^{\\infty}1/n^2$","En":"$\\sum_{n=1}^{\\infty}1/n^2$"},"CommonError":{"Ar":"اقتراب الحدود من الصفر ليس كافياً وحده.","En":"Terms tending to zero are not sufficient."},"FormulaLatex":"\\sum_{n=1}^{\\infty}n^{-p},\\quad p>1","Substitution":{"Ar":"$p=2>1$","En":"$p=2>1$"},"Verification":{"Ar":"$\\int_1^\\infty x^{-2}\\,dx=1<\\infty$","En":"$\\int_1^\\infty x^{-2}\\,dx=1<\\infty$"}},"TrackIds":[13,20],"CategoryId":36,"PrimarySkillId":75,"DifficultyLevel":1,"SecondarySkillIds":[]}$mw$::jsonb,$mw${"DifficultyLevel":1,"Hints":[{"Ar":"صنّف المتسلسلات قبل تطبيق اختبار التقارب.","En":"Classify the series before applying a convergence test."},{"Ar":"للمتسلسلة من الشكل واحد على قوة العدد الطبيعي، قارن الأس بواحد.","En":"For a series of reciprocals of natural-number powers, compare the exponent with one."}],"Solution":{"Idea":{"Ar":"معيار متسلسلة القوى العكسية: $\\sum_{n=1}^{\\infty}1/n^p$ تتقارب إذا وفقط إذا $p>1$. هنا $p=2$.","En":"The p-series test: $\\sum_{n=1}^{\\infty}1/n^p$ converges exactly when $p>1$. Here $p=2$."},"Unit":{"Ar":"بلا وحدة قياس","En":"Dimensionless"},"Steps":[{"Ar":"نستعمل معيار متسلسلة القوى العكسية، الذي يتطلب أساً أكبر من واحد للتقارب.","En":"Use the p-series test, which requires an exponent greater than one for convergence."},{"Ar":"$p=2>1;\\quad p=1,\\quad p=1/2\\le1$","En":"$p=2>1;\\quad p=1,\\quad p=1/2\\le1$"},{"Ar":"المتسلسلة الأولى متقاربة، والثانية والثالثة متباعدتان؛ والمتسلسلة الرابعة متباعدة لأن حدودها لا تؤول إلى الصفر.","En":"The first series converges, the second and third diverge, and the fourth diverges because its terms do not approach zero."}],"Result":{"Ar":"$\\sum_{n=1}^{\\infty}1/n^2$","En":"$\\sum_{n=1}^{\\infty}1/n^2$"},"CommonError":{"Ar":"اقتراب الحدود من الصفر ليس كافياً وحده.","En":"Terms tending to zero are not sufficient."},"FormulaLatex":"\\sum_{n=1}^{\\infty}n^{-p},\\quad p>1","Substitution":{"Ar":"$p=2>1$","En":"$p=2>1$"},"Verification":{"Ar":"$\\int_1^\\infty x^{-2}\\,dx=1<\\infty$","En":"$\\int_1^\\infty x^{-2}\\,dx=1<\\infty$"}},"Distractors":[{"ErrorType":"","Reason":null,"Order":1},{"ErrorType":"incorrect-option","Reason":{"Ar":"المتسلسلة التوافقية لها p=1 وهي متباعدة.","En":"The harmonic series has p=1 and diverges."},"Order":2},{"ErrorType":"incorrect-option","Reason":{"Ar":"الأس 1/2 لا يتجاوز واحداً، لذا تتباعد.","En":"Exponent 1/2 does not exceed one, so the series diverges."},"Order":3},{"ErrorType":"incorrect-option","Reason":{"Ar":"الحد العام ثابت يساوي 1، فيخالف الشرط الضروري للتقارب.","En":"The constant term 1 violates the necessary condition for convergence."},"Order":4}]}$mw$,$mw$معيار متسلسلة القوى العكسية: $\sum_{n=1}^{\infty}1/n^p$ تتقارب إذا وفقط إذا $p>1$. هنا $p=2$.

$\sum_{n=1}^{\infty}n^{-p},\quad p>1$

1. نستعمل معيار متسلسلة القوى العكسية، الذي يتطلب أساً أكبر من واحد للتقارب.

2. $p=2>1;\quad p=1,\quad p=1/2\le1$

3. المتسلسلة الأولى متقاربة، والثانية والثالثة متباعدتان؛ والمتسلسلة الرابعة متباعدة لأن حدودها لا تؤول إلى الصفر.

$p=2>1$

$\sum_{n=1}^{\infty}1/n^2$ بلا وحدة قياس

$\int_1^\infty x^{-2}\,dx=1<\infty$

اقتراب الحدود من الصفر ليس كافياً وحده.$mw$,$mw$The p-series test: $\sum_{n=1}^{\infty}1/n^p$ converges exactly when $p>1$. Here $p=2$.

$\sum_{n=1}^{\infty}n^{-p},\quad p>1$

1. Use the p-series test, which requires an exponent greater than one for convergence.

2. $p=2>1;\quad p=1,\quad p=1/2\le1$

3. The first series converges, the second and third diverge, and the fourth diverges because its terms do not approach zero.

$p=2>1$

$\sum_{n=1}^{\infty}1/n^2$ Dimensionless

$\int_1^\infty x^{-2}\,dx=1<\infty$

Terms tending to zero are not sufficient.$mw$);
DO $audit$
DECLARE b record; d "CurriculumDraftItems"%ROWTYPE; p "Problems"%ROWTYPE; tr int; sk int; n int; actor int;
BEGIN
 FOR b IN SELECT * FROM reviewed_batch ORDER BY source LOOP
  PERFORM pg_advisory_xact_lock(-b.source::bigint);
  SELECT * INTO STRICT d FROM "CurriculumDraftItems" WHERE "Id"=b.draft FOR UPDATE;
  SELECT * INTO STRICT p FROM "Problems" WHERE "Id"=b.source FOR UPDATE;
  PERFORM 1 FROM "QuestionOptions" WHERE "ProblemId"=b.source FOR UPDATE;
  actor:=d."OwnerUserId"; tr:=(b.wizard->'TrackIds'->>0)::int; sk:=(b.wizard->>'PrimarySkillId')::int;
  IF d."SourceProblemId" IS DISTINCT FROM b.source OR d."Revision"<>0 OR d."EditorialStatus"<>'Draft' OR d."PublishedProblemId" IS NOT NULL OR d."SourceFingerprint" IS DISTINCT FROM b.fp OR md5(d."WizardJson") IS DISTINCT FROM b.draft_hash OR upper(encode(sha256(decode(b.source_hex,'hex')),'hex'))<>b.fp OR (SELECT json_build_object('Id',pp."Id",'StageId',pp."StageId",'CategoryId',pp."CategoryId",'Points',pp."Points",'TitleAr',pp."TitleAr",'TitleEn',pp."TitleEn",'QuestionTextAr',pp."QuestionTextAr",'QuestionTextEn',pp."QuestionTextEn",'DetailedSolutionAr',pp."DetailedSolutionAr",'DetailedSolutionEn',pp."DetailedSolutionEn",'YoutubeSolutionUrl',pp."YoutubeSolutionUrl",'EditorialDetailsJson',pp."EditorialDetailsJson",'Options',(select json_agg(json_build_object('Id',o."Id",'Order',o."Order",'LatexCode',o."LatexCode",'IsCorrect',o."IsCorrect") order by o."Order",o."Id") from "QuestionOptions" o where o."ProblemId"=pp."Id"))::jsonb FROM "Problems" pp WHERE pp."Id"=b.source) IS DISTINCT FROM b.snapshot THEN RAISE EXCEPTION 'Source/draft conflict: %',b.draft; END IF;
  IF NOT EXISTS(SELECT 1 FROM "Users" WHERE "Id"=actor AND "Role"='Admin' AND "IsActive" AND NOT "StaffSetupPending") OR (SELECT count(*) FROM "CurriculumDraftItems" WHERE "SourceProblemId"=b.source AND "EditorialStatus" NOT IN ('Published','Withdrawn'))<>1 THEN RAISE EXCEPTION 'Owner/open-draft conflict: %',b.draft; END IF;
  PERFORM 1 FROM "LearningTracks" WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int) ORDER BY "Id" FOR UPDATE;
  IF NOT EXISTS(SELECT 1 FROM "LearningTracks" WHERE "Id"=tr AND "StageId"=p."StageId" AND "IsPublished" AND "Revision"<2147483647) OR NOT EXISTS(SELECT 1 FROM "Categories" WHERE "Id"=p."CategoryId" AND "StageId"=p."StageId") OR NOT EXISTS(SELECT 1 FROM "CurriculumSkills" s JOIN "CurriculumDomains" dm ON dm."Id"=s."DomainId" WHERE s."Id"=sk AND s."StageId"=p."StageId" AND s."CategoryId"=p."CategoryId" AND s."IsPublished" AND dm."IsPublished") OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=tr AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=tr AND "SkillId"=sk) OR (SELECT array_agg("TrackId" ORDER BY "TrackId") FROM "LearningTrackProblems" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY(SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int ORDER BY 1) OR (SELECT array_agg("SkillId" ORDER BY "SkillId") FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source) IS DISTINCT FROM ARRAY[sk] OR NOT EXISTS(SELECT 1 FROM "CurriculumProblemSkills" WHERE "ProblemId"=b.source AND "SkillId"=sk AND "IsPrimary") OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(b.wizard->'TrackIds') j(id) LEFT JOIN "LearningTracks" lt ON lt."Id"=j.id::int WHERE lt."Id" IS NULL OR lt."StageId"<>p."StageId" OR lt."Revision">=2147483647 OR NOT EXISTS(SELECT 1 FROM "LearningTrackCategories" WHERE "TrackId"=lt."Id" AND "CategoryId"=p."CategoryId") OR NOT EXISTS(SELECT 1 FROM "LearningTrackSkills" WHERE "TrackId"=lt."Id" AND "SkillId"=sk)) THEN RAISE EXCEPTION 'Scope conflict: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "Problems" q WHERE q."Id"<>b.source AND q."StageId"=p."StageId" AND (upper(regexp_replace(btrim(q."QuestionTextAr"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextAr"),'[[:space:]]+',' ','g')) OR upper(regexp_replace(btrim(q."QuestionTextEn"),'[[:space:]]+',' ','g'))=upper(regexp_replace(btrim(p."QuestionTextEn"),'[[:space:]]+',' ','g')))) THEN RAISE EXCEPTION 'Duplicate: %',b.draft; END IF;
  IF EXISTS(SELECT 1 FROM "CurriculumDraftItems" x WHERE x."Id"<>b.draft AND x."EditorialStatus" NOT IN ('Published','Withdrawn') AND (x."WizardJson"::jsonb#>>'{Question,Ar}'=p."QuestionTextAr" OR x."WizardJson"::jsonb#>>'{Question,En}'=p."QuestionTextEn")) THEN RAISE EXCEPTION 'Open draft duplicate: %',b.draft; END IF;
  IF b.wizard#>>'{Question,Ar}' IS DISTINCT FROM p."QuestionTextAr" OR b.wizard#>>'{Question,En}' IS DISTINCT FROM p."QuestionTextEn" OR length(b.flat_ar)>12000 OR length(b.flat_en)>12000 THEN RAISE EXCEPTION 'Question/length conflict: %',b.draft; END IF;
  UPDATE "Problems" SET "TitleAr"=b.wizard#>>'{Title,Ar}',"TitleEn"=b.wizard#>>'{Title,En}',"DetailedSolutionAr"=b.flat_ar,"DetailedSolutionEn"=b.flat_en,"EditorialDetailsJson"=b.metadata WHERE "Id"=b.source;
  UPDATE "CurriculumDraftItems" SET "WizardJson"=b.wizard::text,"EditorialStatus"='Published',"Revision"=4,"SubmittedAtUtc"=now(),"ReviewedAtUtc"=now(),"ReviewedByUserId"=actor,"ReviewNote"='Owner-authorized SQL maintenance; AI educational review and source-locked verification. Existing draft owner recorded for attribution; no API login.',"PublishedAtUtc"=now(),"PublishedProblemId"=b.source WHERE "Id"=b.draft;
  UPDATE "LearningTracks" SET "Revision"="Revision"+1 WHERE "Id" IN (SELECT jsonb_array_elements_text(b.wizard->'TrackIds')::int);
  INSERT INTO "PlatformActivityEvents"("ActorUserId","ActorRole","Action","Resource","ResourceId","Origin","CreatedAtUtc") SELECT actor,'Admin',action,'EditorialProblem',b.draft::text,'owner_sql',now() FROM unnest(ARRAY['EditorialDraftEdited','EditorialDraftSubmitted','EditorialDraftApproved','EditorialAmendmentPublished']) action;
 END LOOP;
END $audit$;
COMMIT;
